from c8e_base import *
LB(8,3,'Language work: phrasal verbs, confusing word pairs, spoonerisms, pronunciation and a news report','Language work for the mystery chapter: phrasal verbs, homophones, spoonerisms and report writing','Solving word mysteries',
 "A detective story gives us phrasal verbs, pairs of words that sound alike, a funny speech slip called a spoonerism, tricky pronunciations and the way to write a report on an event.",
 [("A phrasal verb is a verb joined with a small word, and its meaning is often different from the parts. Put on means wear, cool down means become calm, turn up means appear or be discovered, and make of means have an idea or understanding of something.","put on, cool down, turn up, make of"),
  ("Figure out means solve a problem, and get away with means escape without being punished. Example: 'Important evidence has turned up' and 'He put on his special coat'.","figure out, get away with"),
  ("Some words sound the same but are spelt differently and mean different things. Week is seven days and weak means not strong. Dying is losing life and dyeing is colouring cloth or hair. Fore means front and four is the number. Peace is calm and piece is a part. Break is to split and brake slows a vehicle.","week/weak, dying/dyeing, fore/four, peace/piece, break/brake"),
  ("To choose the right word, read the sentence and decide the meaning needed. 'She used too much force on the brake, causing the car to break down' needs brake for the pedal and break for the failure.","choose by meaning"),
  ("A spoonerism is a speech slip where the first sounds of words in a phrase are swapped, usually giving a funny meaning. 'Wrong load' for 'long road' and 'round of mice' for 'mound of rice' are examples.","spoonerism"),
  ("To fix a spoonerism, swap the first sounds back until the phrase makes sense. 'Plaster man' becomes 'master plan', and 'blarm wanket' becomes 'warm blanket'.","undoing a spoonerism"),
  ("Pronunciation practice: jewellery (jool-ree), clerk (claak), dessert (dih-zuht) which is a sweet dish, January (ja-nyoo-uh-ree), sour (sau-uh), pizza (peet-zaa), Wednesday (wenz-day), bowl (bol) and buffet (buh-fay).","jewellery, clerk, dessert, Wednesday, buffet"),
  ("A report is written for an event that has already occurred. It gives first-hand details in proper sequence with a title, a byline (the reporter's name and class), and paragraphs that answer What, Who, When, Where and Why. A report is in the past tense.","report format")],
 ("Fill in: (a) The brake failed and the car had to ___ down. (b) The teacher's story brought ___ to the class. Which words fit?",
  [("(a) break, because the car stopped working.","The verb meaning stop working."),
   ("(b) peace, meaning calm.","Pick the noun for calm.")]),
 ("Explain what a phrasal verb is with one example, and list the details a news report should answer.",
  ["a verb joined with a small word; put on means wear","What, Who, When, Where and Why","A report uses the past tense and a title and byline"],
  ["Using weak for week","Writing a report in the future tense"]),
 ["A phrasal verb gives a new meaning, such as put on or turn up.","Homophones differ in spelling and meaning: week/weak, peace/piece.","A spoonerism swaps first sounds.","A report is written after the event, in the past tense, with a title and byline."],
 [mcq("v3a-1",1,"'Turn up' in 'evidence has turned up' means","appeared or been discovered",[("wear clothes","That is put on."),("escape punishment","That is get away with.")],"It appeared."),
  mcq("v3a-2",1,"'Figure out' means","solve a problem",[("become calm","That is cool down."),("wear","That is put on.")],"Find the answer."),
  mcq("v3a-3",1,"'Weak' means","not strong",[("seven days","That is week."),("front","That is fore.")],"Weak is not strong."),
  mcq("v3a-4",2,"Complete: She used too much force on the ___.","brake",[("break","Break means split or stop working."),("brack","Not a word.")],"A brake slows a vehicle."),
  mcq("v3a-5",2,"A spoonerism is","a slip where first sounds of words are swapped",[("a long speech","Not this."),("a poem","Not this.")],"Sounds are swapped."),
  mcq("v3a-6",2,"'Wrong load' is a spoonerism of","long road",[("strong road","Not correct."),("long load","Only one sound is swapped.")],"Swap the first sounds w and l."),
  tf("v3a-7",2,"A report is written for an event that has already occurred.",True,"A report is after the event."),
  mcq("v3a-8",3,"Which is NOT part of a report's format?","a rhyme scheme",[("title and byline","Part of a report."),("What, Who, When, Where paragraphs","Part of a report.")],"A rhyme scheme belongs to a poem."),
  mcq("v3a-9",3,"The correct pronunciation guide for 'clerk' is","claak",[("clurk-ee","Not this."),("clark-ee","Not this.")],"Clerk is pronounced claak.")])
LB(8,3,'Language work: words with several meanings, interjections, falling tone and imaginative essay','Language work for the poem on the magic brush: draw, interjections, falling tone and imaginative essay','One word, many meanings',
 "A poem about a magic brush brings us to a word with many meanings, short words of feeling, the tone of a command and a creative essay.",
 [("The verb draw has different meanings in different contexts. A speech can draw loud applause (get a reaction), an event can draw huge crowds (attract), and plants draw water (absorb) from the soil.","draw: get a reaction, attract, absorb"),
  ("A train draws into the station (moving), she drew the curtains (opened them), and he drew a paper from the folder (pulled it out). Always decide the meaning from the sentence.","draw: moving, opened, pulled out"),
  ("Interjections show sudden feelings. Phew! shows relief, Eek! alarm, Ouch! pain, Yippee! delight, Whoa! surprise, Oops! a mistake and Hey! attracts attention.","Phew, Eek, Ouch, Yippee, Whoa, Oops, Hey"),
  ("In a sentence, the interjection is followed by an exclamation mark: 'Ouch! I hurt my finger' and 'Yippee! We won the match'.","using interjections"),
  ("Intonation is the rise and fall of the pitch of your voice. The falling tone drops from a high level to a low level and is generally used in imperative sentences, such as commands, instructions, requests for a favour or warnings.","falling tone"),
  ("Read these with a falling tone: 'Come here!', 'Seize this magic brush', 'Paint my fortress tall!' and 'Go and fetch some rice'. Take turns making formal and informal requests in pairs.","reading with falling tone"),
  ("An imaginative essay is a creative piece that uses imagination. It can be based on real-life events, observation or experience, and is usually a descriptive piece or a personal reflection. A good one starts with a hook, like 'Imagine an ordinary 13-year-old who is also a secret superhero'.","imaginative essay"),
  ("To plan your essay: pick a character or idea, describe the powers or setting, show a problem and how it is solved, and end with what you learnt or feel.","planning an imaginative essay")],
 ("Match the meaning of 'draw' in: (a) 'Plants draw water from the soil.' (b) 'She drew the curtains.' Then pick an interjection for dropping a glass.",
  [("(a) absorb.","Plants take in water."),
   ("(b) opened (or pulled across the window).","Curtains were moved."),
   ("Oops!, showing a mistake.","A mistake is Oops.")]),
 ("Explain the falling tone and when it is used, and give two interjections with their emotions.",
  ["The pitch falls from high to low","It is used for commands, instructions, requests and warnings","Phew! shows relief and Ouch! shows pain"],
  ["Using a rising tone for commands","Forgetting the exclamation mark after an interjection"]),
 ["draw has many meanings: get a reaction, attract, absorb, move, open, pull out.","Interjections show sudden feelings: Phew, Eek, Ouch, Yippee, Whoa, Oops, Hey.","The falling tone suits commands and warnings.","An imaginative essay uses creative description and a hook."],
 [mcq("v3b-1",1,"'The event will draw huge crowds' uses draw to mean","attract",[("absorb","Not here."),("open","Not here.")],"Attract."),
  mcq("v3b-2",1,"'Plants draw water' means plants","absorb water",[("paint water","Not this."),("pull water","Absorb is the idea.")],"Absorb."),
  mcq("v3b-3",1,"'Phew!' shows","relief",[("pain","That is Ouch."),("alarm","That is Eek.")],"Relief."),
  mcq("v3b-4",1,"'Oops!' shows","a mistake",[("delight","That is Yippee."),("surprise","That is Whoa.")],"Mistake."),
  mcq("v3b-5",2,"The falling tone is generally used in","imperative sentences",[("questions with yes or no","Those use a rising tone."),("lists","Not here.")],"Commands and instructions."),
  mcq("v3b-6",2,"'Hey!' is used to","attract attention",[("show pain","That is Ouch."),("show relief","That is Phew.")],"Hey calls attention."),
  tf("v3b-7",2,"An imaginative essay can be based on real-life observation.",True,"It may be based on real life or imagination."),
  mcq("v3b-8",3,"A good opening for an imaginative essay is","a hook that draws the reader in",[("a formal address","Not for an essay."),("a list of rules","Not a hook.")],"Hooks catch interest."),
  mcq("v3b-9",3,"'She drew the curtains' means she","opened or pulled the curtains",[("painted the curtains","Not this."),("sold the curtains","Not this.")],"Moved the curtains.")])
